    public static function subjects(): array
    {
        return self::SUBJECTS;
    }

    public static function questions(?string $subject = null): array
    {
        $subjects = $subject === null ? array_keys(self::SUBJECTS) : [$subject];
        $questions = [];

        foreach ($subjects as $subjectKey) {
            if (! isset(self::QUESTION_BANK[$subjectKey])) {
                continue;
            }

            foreach (self::QUESTION_BANK[$subjectKey] as $index => [$prompt, $options, $answerIndex, $explanation]) {
                $questions[] = [
                    'id' => sprintf('%s-%03d', $subjectKey, $index + 1),
                    'subject' => $subjectKey,
                    'prompt' => $prompt,
                    'options' => $options,
                    'answer' => $options[$answerIndex],
                    'explanation' => $explanation,
                ];
            }
        }

        return $questions;
    }
}
